-- Remove postes-lixo da importação antiga do parque Ipojuca.
-- Mantém só os Códigos da planilha oficial (10.417).
-- Chamados em CODIGO-N passam para o poste CODIGO; sem match ficam sem poste.
--
-- 1) Rode o bloco PREVIEW e confira os números.
-- 2) Se "lixo" estiver perto de 3383 e "manter" perto de 10417, rode o bloco APLICAR.
-- 3) Tudo em uma única sessão do phpMyAdmin.

SET NAMES utf8mb4;

SET @scope := (
  SELECT id FROM clientes
  WHERE empresa_id IS NULL
    AND (empresa LIKE '%Ipojuca%' OR nome LIKE '%Ipojuca%')
  ORDER BY id
  LIMIT 1
);

-- Se não achar Ipojuca, descomente e coloque o ID da empresa:
-- SET @scope := 1;

SELECT @scope AS empresa_id;

DROP TABLE IF EXISTS tmp_codigos_oficiais_parque;
CREATE TABLE tmp_codigos_oficiais_parque (
  codigo VARCHAR(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_uca1400_ai_ci NOT NULL PRIMARY KEY
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;





















































-- =============================================================================
-- PREVIEW (só leitura)
-- =============================================================================
SELECT
  (SELECT COUNT(*) FROM pontos_iluminacao pi
    WHERE pi.cliente_id IN (SELECT id FROM clientes WHERE id = @scope OR empresa_id = @scope)
  ) AS total_no_banco,
  (SELECT COUNT(*) FROM tmp_codigos_oficiais_parque) AS oficiais_planilha,
  (SELECT COUNT(*) FROM pontos_iluminacao pi
    INNER JOIN tmp_codigos_oficiais_parque t ON t.codigo COLLATE utf8mb4_bin = pi.codigo_poste COLLATE utf8mb4_bin
    WHERE pi.cliente_id IN (SELECT id FROM clientes WHERE id = @scope OR empresa_id = @scope)
  ) AS manter,
  (SELECT COUNT(*) FROM pontos_iluminacao pi
    LEFT JOIN tmp_codigos_oficiais_parque t ON t.codigo COLLATE utf8mb4_bin = pi.codigo_poste COLLATE utf8mb4_bin
    WHERE pi.cliente_id IN (SELECT id FROM clientes WHERE id = @scope OR empresa_id = @scope)
      AND t.codigo IS NULL
  ) AS lixo,
  (SELECT COUNT(*) FROM chamados ch
    INNER JOIN pontos_iluminacao pi ON pi.id = ch.ponto_iluminacao_id
    LEFT JOIN tmp_codigos_oficiais_parque t ON t.codigo COLLATE utf8mb4_bin = pi.codigo_poste COLLATE utf8mb4_bin
    WHERE pi.cliente_id IN (SELECT id FROM clientes WHERE id = @scope OR empresa_id = @scope)
      AND t.codigo IS NULL
  ) AS chamados_no_lixo;

SELECT pi.id, pi.codigo_poste
FROM pontos_iluminacao pi
LEFT JOIN tmp_codigos_oficiais_parque t ON t.codigo COLLATE utf8mb4_bin = pi.codigo_poste COLLATE utf8mb4_bin
WHERE pi.cliente_id IN (SELECT id FROM clientes WHERE id = @scope OR empresa_id = @scope)
  AND t.codigo IS NULL
ORDER BY pi.codigo_poste
LIMIT 30;

-- =============================================================================
-- APLICAR
-- =============================================================================
START TRANSACTION;

-- Chamados em 649495065-31 → poste oficial 649495065 (mesmo cliente)
UPDATE chamados ch
INNER JOIN pontos_iluminacao lixo ON lixo.id = ch.ponto_iluminacao_id
INNER JOIN pontos_iluminacao oficial
        ON oficial.cliente_id = lixo.cliente_id
       AND oficial.codigo_poste = SUBSTRING_INDEX(lixo.codigo_poste, '-', 1)
       AND oficial.id <> lixo.id
LEFT JOIN tmp_codigos_oficiais_parque t ON t.codigo COLLATE utf8mb4_bin = lixo.codigo_poste COLLATE utf8mb4_bin
SET ch.ponto_iluminacao_id = oficial.id
WHERE lixo.cliente_id IN (SELECT id FROM clientes WHERE id = @scope OR empresa_id = @scope)
  AND t.codigo IS NULL
  AND lixo.codigo_poste REGEXP '^[0-9]+-[0-9]+$';

-- Fotos do lixo caem no CASCADE. Chamados sem remap ficam NULL (SET NULL).
DELETE pi
FROM pontos_iluminacao pi
LEFT JOIN tmp_codigos_oficiais_parque t ON t.codigo COLLATE utf8mb4_bin = pi.codigo_poste COLLATE utf8mb4_bin
WHERE pi.cliente_id IN (SELECT id FROM clientes WHERE id = @scope OR empresa_id = @scope)
  AND t.codigo IS NULL;

SELECT
  (SELECT COUNT(*) FROM pontos_iluminacao pi
    WHERE pi.cliente_id IN (SELECT id FROM clientes WHERE id = @scope OR empresa_id = @scope)
  ) AS parque_restante;

-- Se o restante estiver perto de 10417:
COMMIT;
-- Se algo estiver errado:
-- ROLLBACK;

DROP TABLE IF EXISTS tmp_codigos_oficiais_parque;